def _selected_git_paths(workspace: Path, paths: list[str]) -> list[str]:
    """Keep existing paths plus tracked deletions; drop create-then-revert history paths."""
    selected = sorted({str(path).strip().replace("\\", "/") for path in paths if str(path).strip()})
    if not selected:
        return []

    kept = {
        rel for rel in selected
        if (workspace / rel).exists() or (workspace / rel).is_symlink()
    }
    missing = [rel for rel in selected if rel not in kept]
    if missing:
        tracked = subprocess.run(
            ["git", "ls-tree", "-r", "--name-only", "HEAD", "--", *missing],
            cwd=workspace,
            text=True,
            capture_output=True,
            timeout=30,
        )
        if tracked.returncode == 0:
            kept.update(line.strip() for line in tracked.stdout.splitlines() if line.strip())
    return sorted(kept)


